        }
        const idx = book.holds.indexOf(memberId);
        if (idx !== -1) {
          const readyUntil = idx === 0 && book.readyUntil !== null ? formatDay(book.readyUntil) : null;
          holds.push({ bookId, position: idx + 1, readyUntil });
        }
      }
      return { ok: true, loans, owed: member.owed, holds };
    },
  };
